import re

_UNITS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'week': 604800, 'weeks': 604800,
}

_NUM = r'\d+(?:\.\d+)?'


def _round(total: float) -> int:
    return int(total + 0.5)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("input must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # Bare integer: seconds.
    if re.fullmatch(r'\d+', s):
        return int(s)

    # Clock notation: hh:mm:ss or mm:ss.
    m = re.fullmatch(r'(\d+):(\d{1,2})(?::(\d{1,2}))?', s)
    if m:
        a, b, c = m.groups()
        if c is None:
            return int(a) * 60 + int(b)
        return int(a) * 3600 + int(b) * 60 + int(c)

    # ISO 8601 duration.
    if s[0] in 'Pp':
        m = re.fullmatch(
            r'P(?:(%(n)s)W)?(?:(%(n)s)D)?'
            r'(?:T(?:(%(n)s)H)?(?:(%(n)s)M)?(?:(%(n)s)S)?)?' % {'n': _NUM},
            s, re.IGNORECASE)
        if not m or not any(m.groups()):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        w, d, h, mi, sec = (float(g) if g else 0.0 for g in m.groups())
        return _round(w * 604800 + d * 86400 + h * 3600 + mi * 60 + sec)

    # Number+unit components.
    pattern = re.compile(r'\s*(%s)\s*([a-zA-Z]+)' % _NUM)
    pos = 0
    total = 0.0
    found = False
    while pos < len(s):
        m = pattern.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {unit!r} in {text!r}")
        total += float(m.group(1)) * _UNITS[unit]
        found = True
        pos = m.end()
        while pos < len(s) and s[pos].isspace():
            pos += 1
    if not found:
        raise ValueError(f"invalid duration: {text!r}")
    return _round(total)

